260	OpDesc::OpDesc(const proto::OpDesc &desc, BlockDesc *block)
261	    : desc_(desc), need_update_(false) {
262	  // restore inputs_
263	  int input_size = desc_.inputs_size();
264	  for (int i = 0; i < input_size; ++i) {
265	    const proto::OpDesc::Var &var = desc_.inputs(i);
266	    std::vector<std::string> &args = inputs_[var.parameter()];
267	    int argu_size = var.arguments_size();
268	    args.reserve(argu_size);
269	    for (int j = 0; j < argu_size; ++j) {
270	      args.push_back(var.arguments(j));
271	    }
272	  }
273	  // restore outputs_
274	  int output_size = desc_.outputs_size();
275	  for (int i = 0; i < output_size; ++i) {
276	    const proto::OpDesc::Var &var = desc_.outputs(i);
277	    std::vector<std::string> &args = outputs_[var.parameter()];
278	    int argu_size = var.arguments_size();
279	    args.reserve(argu_size);
280	    for (int j = 0; j < argu_size; ++j) {
281	      args.push_back(var.arguments(j));
282	    }
283	  }
284	  // restore attrs_
285	  for (const proto::OpDesc::Attr &attr : desc_.attrs()) {
286	    std::string attr_name = attr.name();
287	    // The sub_block referred to by the BLOCK attr hasn't been added
288	    // to ProgramDesc class yet, we skip setting BLOCK/BLOCKS attr here.
289	    if (attr.type() != proto::AttrType::BLOCK &&
290	        attr.type() != proto::AttrType::BLOCKS) {
291	      attrs_[attr_name] = GetAttrValue(attr);
292	    }
293	  }
294	  this->block_ = block;
295	}
