25	int PaddleDtypeSize(PaddleDType dtype) {
26	  switch (dtype) {
27	    case PaddleDType::FLOAT32:
28	      return sizeof(float);
29	    case PaddleDType::INT64:
30	      return sizeof(int64_t);
31	    case PaddleDType::INT32:
32	      return sizeof(int32_t);
33	    default:
34	      assert(false);
35	      return -1;
36	  }
