50	PaddleBuf &PaddleBuf::operator=(const PaddleBuf &other) {
51	  if (!other.memory_owned_) {
52	    data_ = other.data_;
53	    length_ = other.length_;
54	    memory_owned_ = other.memory_owned_;
55	  } else {
56	    Resize(other.length());
57	    memcpy(data_, other.data(), other.length());
58	    length_ = other.length();
59	    memory_owned_ = true;
60	  }
61	  return *this;
62	}
