64	PaddleBuf &PaddleBuf::operator=(PaddleBuf &&other) {
65	  // only the buffer with external memory can be copied
66	  data_ = other.data_;
67	  length_ = other.length_;
68	  memory_owned_ = other.memory_owned_;
69	  other.data_ = nullptr;
70	  other.length_ = 0;
71	  other.memory_owned_ = false;
72	  return *this;
73	}
