75	void PaddleBuf::Resize(size_t length) {
76	  // Only the owned memory can be reset, the external memory can't be changed.
77	  if (length_ >= length) return;
78	  if (memory_owned_) {
79	    Free();
80	    data_ = malloc(length);
81	    length_ = length;
82	    memory_owned_ = true;
83	  } else {
84	    PADDLE_THROW("The memory is allocated externally, can not Resized");
85	  }
86	}
87	
88	void PaddleBuf::Reset(void *data, size_t length) {
89	  Free();
90	  memory_owned_ = false;
91	  data_ = data;
92	  length_ = length;
93	}
