95	void PaddleBuf::Free() {
96	  if (memory_owned_ && data_) {
97	    PADDLE_ENFORCE_GT(length_, 0UL);
98	    free(static_cast<char *>(data_));
99	    data_ = nullptr;
100	    length_ = 0;
101	  }
102	}
